public boolean shouldPrintMessage(int timestamp, String message) {
    // Retrieve the message frequency and timestamp from the message map
    int freq = MESSAGE_FREQ_MAP.get(message);
    long lastPrintedTimestamp = LAST_PRINTED_TIMESTAMP_MAP.get(message);

    // Calculate the current interval based on the frequency
    long currentInterval = System.currentTimeMillis() - lastPrintedTimestamp;

    // Check if the current interval is greater than the frequency and if the message should be printed
    if (currentInterval > (freq * 1000L) && timestamp - lastPrintedTimestamp >= (freq * 1000L)) {
        // Update the last printed timestamp for the message
        LAST_PRINTED_TIMESTAMP_MAP.put(message, timestamp);
        return true;
    } else {
        return false;
    }
}

