    // Return null if the input array is null
    if (array == null) {
        return null;
    }

    // Create a new array of primitives with the same length as the input array
    boolean[] result = new boolean[array.length];

    // Loop through each element in the input array and convert it to a primitive
    for (int i = 0; i < array.length; i++) {
        result[i] = array[i] == null ? false : array[i];
    }

    // Return the new array of primitives
    return result;
}

