public static String reverse(String str) {
    if (str == null) {
        return null;
    }

    int strLen = str.length();
    if (strLen == 0) {
        return "";
    }

    int mid = strLen / 2;
    for (int i = 0; i < mid; i++) {
        int j = strLen - i - 1;
        char temp = str.charAt(i);
        str.setCharAt(i, str.charAt(j));
        str.setCharAt(j, temp);
    }

    return str;
}

