public static String reverse(String str) {
    if (str == null) {
        return null;
    }
    int len = str.length();
    if (len < 2) {
        return str;
    }
    StringBuilder buf = new StringBuilder(len);
    for (int i = len - 1; i >= 0; i--) {
        buf.append(str.charAt(i));
    }
    return buf.toString();
}

