    int newCapacity = capacity() + size;
    // If the new capacity exceeds the maximum allowed capacity, throw an exception
    if (newCapacity > MAX_CAPACITY) {
        throw new IllegalStateException("Maximum capacity exceeded: " + newCapacity);
    }
    // Create a new byte array of the required size
    byte[] newBytes = new byte[newCapacity];
    // Copy the existing bytes to the new byte array
    System.arraycopy(bytes, 0, newBytes, 0, size());
