final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    int index = constantPoolEntryIndex;
    if (index < 0 || index > constantPool.length) {
        throw new IllegalArgumentException("Invalid constant pool index: " + index);
    }
    int length = constantPool[index].length;
    if (length == 0) {
        return "";
    }
    if (charBuffer.length < length) {
        throw new IllegalArgumentException("Insufficient space in char buffer: " + charBuffer.length + " bytes, required: " + length + " bytes");
    }
    // Read the string from the constant pool
    for (int i = 0; i < length; i++) {
        charBuffer[i] = constantPool[index][i];
    }
    return new String(charBuffer, 0, length);
}

