public void generateGraph(Graph<V,E> target, Map<String, V> resultMap) {
        // Create a new graph if none is provided
        if (target == null) {
            target = new Graph<V, E>();
        }

        // Get the number of vertices and edges from the result map
        int numVertices = resultMap.size();
        int numEdges = 0;

        // Add vertices to the graph
        for (Map.Entry<String, V> entry : resultMap.entrySet()) {
            target.addVertex(entry.getValue());
            numEdges += entry.getValue().getDegree();
        }

        // Add edges to the graph
        for (Map.Entry<String, V> entry : resultMap.entrySet()) {
            V vertex = entry.getValue();
            for (E edge : vertex.getEdges()) {
                if (resultMap.containsKey(edge.getOtherEnd(vertex).getLabel())) {
                    target.addEdge(edge);
                }
            }
        }

        // Check that the graph is valid
        assert(target.isValidGraph());
    }

