private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Decode octets in bb using the UTF-8 decoding and append the result to sb
    int next = i;
    while (bb.hasRemaining()) {
        char c = bb.get();
        if (Character.isHighSurrogate(c)) {
            int low = bb.get();
            if (Character.isLowSurrogate(low)) {
                sb.append(Character.toChars(c, low));
            } else {
                sb.append(c);
                i--;
            }
        } else {
            sb.append(c);
        }
    }
    return next;
}

