public final MatchResult match(URI uri) {
    if (uri == null) {
        return null;
    }

    // Strip out any query string or fragment from the URI
    // so as to produce a match to the original template
    String strippedUri = StringUtils.stripEnd(uri.getPath() + uri.getQuery(), "/#");

    // If the stripped URI is equal to the template, return a match result with all groups empty
    if (strippedUri.equals(template)) {
        return createMatchResult(new String[0]);
    }

    // If the stripped URI matches the template, run the regular expression and return a match result with all groups populated
    Matcher m = templateRegex.matcher(strippedUri);
    if (m.matches()) {
        int n = m.groupCount();
        String[] groups = new String[n];
        for (int i = 0; i < n; i++) {
            groups[i] = m.group(i + 1);
        }
        return createMatchResult(groups);
    }

    // Otherwise return null
    return null;
}

