public static File[] getClassPath(){

    // Get the system class path for the current JVM instance
    String classPath = System.getProperty("java.class.path");

    // Split the class path string into an array of file names using the system path separator
    String[] fileNames = classPath.split(System.getProperty("path.separator"));

    // Initialize an empty list to store all the resulting File objects
    List<File> fileList = new ArrayList<>();

    // Iterate over each file name and create a File object for each one
    for (int i = 0; i < fileNames.length; i++){
        String filePath = fileNames[i];
        File file = new File(filePath);
        fileList.add(file);
    }

    // Return the list of File objects as an array
    return fileList.toArray(new File[fileList.size()]);
}

