public Action inspect(AtmosphereResource r) {
    // Extract the transport type from the resource
    AtmosphereResource.TRANSPORT transport = r.getTransport();

    // Implement the auto-suspension logic based on the transport type
    switch (transport) {
        case HTTP:
            // If the transport is HTTP, auto-suspend if the resource is not closed and has accumulated 10MB of messages
            if (!r.isClosed() && r.getmessages().size() >= 10) {
                r.suspend();
            }
            break;
        case HTTP_POLLING:
            // If the transport is HTTP polling, auto-suspend if the resource is not closed and has accumulated 10MB of messages
            if (!r.isClosed() && r.getmessages().size() >= 10) {
                r.suspend();
            }
            break;
        default:
            // If the transport is not HTTP or HTTP polling, do nothing
            break;
    }

    // Always return CONTINUE to continue processing the resource
    return Action.CONTINUE;
}

