void add(LoggingEvent event) {
    boolean eventAdded = false;
    try {
        // Check if the event has already been added
        if (!eventBuffer.contains(event)) {
            // Add the event to the buffer
            eventBuffer.add(event);
            // Notify any listeners that the buffer has changed
            notifyListeners();
            eventAdded = true;
        }
    } catch (Exception e) {
        // Handle any exceptions while adding the event
        // Log the exception and return false
        logger.error("Exception occurred while adding event to buffer", e);
    } finally {
        // Return true if the event was added successfully, false otherwise
        return eventAdded;
    }
}

