private void removeAppender(String name) {
    if (name == null || name.isEmpty()) {
        return;
    }

    List<Appender> appenders = getAppenders();
    if (appenders == null || appenders.isEmpty()) {
        return;
    }

    Iterator<Appender> iter = appenders.iterator();
    while (iter.hasNext()) {
        Appender appender = iter.next();
        if (name.equals(appender.getName())) {
            iter.remove();
            break;
        }
    }
}

