    if (!Character.isLetter(buf.charAt(nameStart)) || Character.isWhitespace(buf.charAt(nameStart + 1))) {
        throw new IllegalArgumentException("Input is not a valid name");
    }

    // Initialize variables
    int i = nameStart + 2;
    int last = nameStart + 1;

    // Iterate through the remaining characters
    while (i < buf.length()) {
        char c = buf.charAt(i);

        // Check if the current character is a space or an uppercase letter
        if (Character.isWhitespace(c) || Character.isUpperCase(c)) {
            // Add the current name to the abbreviation
            buf.insert(last, buf.substring(nameStart, i));

            // Set the last position to the current position
            last = i;

            // Check if the current character is a space
            if (Character.isWhitespace(c)) {
                // Add a dot between the names
                buf.insert(last, '.');

                // Set the last position to the current position
                last = i + 1;
            }

            // Set the new name start position
            nameStart = i;
        }

        // Increment the counter i
        i++;
    }

    // Add the last name to the abbreviation
    buf.insert(last, buf.substring(nameStart));
}

