protected List<TimeRange> buildTimeRanges(long start, long end) {
    long duration = end - start;
    long numRanges = duration / FETCH_DATA_DURATION;
    List<TimeRange> timeRanges = new ArrayList<>((int) numRanges);
    for (int i = 0; i < numRanges; i++) {
        long rangeStart = start + (i * FETCH_DATA_DURATION);
        long rangeEnd = rangeStart + FETCH_DATA_DURATION;
        if (rangeEnd > end) {
            rangeEnd = end;
        }
        timeRanges.add(new TimeRange(rangeStart, rangeEnd));
    }
    return timeRanges;
