private static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 1000) {
        return 1009; // prime number just below 1000
    }

    // Use the Sieve of Eratosthenes to find the prime number nearest to the desired capacity
    boolean[] primes = new boolean[desiredCapacity + 1];
    Arrays.fill(primes, true);
    primes[0] = primes[1] = false;
    for (int i = 2; i * i <= desiredCapacity; i++) {
        if (primes[i]) {
            for (int j = i * i; j <= desiredCapacity; j += i) {
                primes[j] = false;
            }
        }
    }

    // Find the first prime number greater than or equal to the desired capacity
    for (int i = desiredCapacity; i <= desiredCapacity + 100; i++) {
        if (primes[i]) {
            return i;
        }
    }

    // This should never happen, just in case the loop is executed more than 100 times
    throw new IllegalArgumentException("Cannot find a prime number larger than " + desiredCapacity);
}

